import lightning as L
import torch
from torch import nn

class Regressor(L.LightningModule):
    def __init__(self):
        super().__init__()
        self.net = nn.Linear(4, 1)

    def training_step(self, batch, _):
        x, y = batch
        return nn.functional.mse_loss(self.net(x), y)

    def configure_optimizers(self):
        return torch.optim.Adam(self.parameters(), lr=1e-2)

data = torch.utils.data.TensorDataset(torch.randn(256, 4), torch.randn(256, 1))
L.Trainer(max_epochs=5, accelerator="auto").fit(Regressor(), torch.utils.data.DataLoader(data, batch_size=32))
